import sys
import threading
import traceback

from functools import partial

from taf.rfrl.utilities.robot.RobotThreads import RobotThreads

from taf.rfrl.csv4all.resources.utilities.utilities import test_logger


class ThreadsRunner(RobotThreads):

    def __init__(self):
        super().__init__()
        self.thread_results = {"Passed": {}, "Failed": {}}

    class TracedThread(threading.Thread):
        def __init__(self, *args, **keywords):
            threading.Thread.__init__(self, daemon=True, *args, **keywords)
            self.killed = False

        def start(self):
            self.__run_backup = self.run
            self.run = self.__run
            threading.Thread.start(self)

        def __run(self):
            sys.settrace(self.globaltrace)
            self.__run_backup()
            self.run = self.__run_backup

        def globaltrace(self, frame, event, arg):
            if event == 'call':
                return self.localtrace
            else:
                return None

        def localtrace(self, frame, event, arg):
            if self.killed:
                if event == 'line':
                    raise Exception
            return self.localtrace

        def kill(self):
            self.killed = True

    def create_thread(self, thread_name, function, *args, **kwargs):
        func = partial(self.return_from_thread, thread_name, function, *args, **kwargs)
        thread = self.TracedThread(name=thread_name, target=func)
        self.threads_messages[thread_name] = []
        self.threads.append(thread)
        thread.start()

    def wait_until_all_threads_finished(self):
        while True in [t.is_alive() for t in self.threads]:
            [t.join(2) for t in self.threads if t is not None and t.is_alive()]

    def __exit__(self, exc_type, exc_val, exc_tb):
        try:
            self.wait_until_all_threads_finished()
        except Exception as e:
            if "Execution terminated by signal" in e.__str__():
                for thr in self.threads:
                    if thr.is_alive():
                        thr.kill()
                self.wait_until_all_threads_finished()
            raise
        finally:
            self.stop_capturing_messages()
            self._revert_signal_handle_in_thread()
            self._write_captured_messages()

    def _write_captured_messages(self):
        for thread_name in [thread.name for thread in self.threads]:
            self.write_captured_messages(thread_name=thread_name)

    def return_from_thread(self, thread_name, func, *args, **kwargs):
        try:
            return_from_func = func(*args, **kwargs)
            self.thread_results["Passed"][thread_name] = return_from_func
        except Exception as e:
            self.thread_results["Failed"][thread_name] = e
            test_logger(traceback.format_exc(), log_level="DEBUG", console=False)
